"""Durable local runtime state. Files remain the policy authority."""
from __future__ import annotations

import json
import os
import base64
import secrets
import re
import sqlite3
import time
from contextlib import contextmanager
from dataclasses import asdict
from pathlib import Path
from typing import Any, Iterator
from uuid import uuid4

from acira_cdp_proxy.redaction import redact_value


def journal_redact(value: Any) -> Any:
    """Redact content while retaining typed routing identifiers generated by Acira."""
    redacted = redact_value(value)
    def restore(source: Any, output: Any) -> None:
        if isinstance(source, dict) and isinstance(output, dict):
            for key, item in source.items():
                pattern = None
                if key in {"revision", "policy_revision", "grant_id"}:
                    pattern = r"[a-f0-9]{64}"
                elif key in {"event_id", "operation_id", "review_id", "project_id"}:
                    pattern = r"(?:review-)?[a-f0-9]{12,32}"
                elif key == "run_id":
                    pattern = r"run-[a-f0-9]{12,32}"
                elif key == "id" and source.get("capture_status") == "ready":
                    pattern = r"[a-f0-9]{32}\.png"
                if pattern and isinstance(item, str) and re.fullmatch(pattern, item):
                    output[key] = item
                elif key in output:
                    restore(item, output[key])
        elif isinstance(source, list) and isinstance(output, list):
            for original, masked in zip(source, output):
                restore(original, masked)
    restore(value, redacted)
    return redacted


class Journal:
    def __init__(self, root: Path) -> None:
        self.path = root / ".acira/runtime.sqlite3"
        self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        if self.path.is_symlink():
            raise PermissionError("Runtime database cannot be a symbolic link")
        with self.db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,
                  id TEXT UNIQUE NOT NULL, run TEXT, created REAL NOT NULL, payload TEXT NOT NULL);
                CREATE INDEX IF NOT EXISTS events_run ON events(run, seq);
                CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, updated REAL NOT NULL, payload TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, run TEXT NOT NULL, state TEXT NOT NULL,
                  expires REAL NOT NULL, payload TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS controls(run TEXT PRIMARY KEY, desired TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY, run TEXT NOT NULL, expires REAL NOT NULL, payload TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS journal_limits(name TEXT PRIMARY KEY, value INTEGER NOT NULL);
                INSERT OR IGNORE INTO journal_limits VALUES('audit_bytes',1073741824);
                INSERT OR IGNORE INTO journal_limits VALUES('image_bytes',262144000);
                CREATE TABLE IF NOT EXISTS journal_usage(name TEXT PRIMARY KEY, value INTEGER NOT NULL);
                INSERT OR IGNORE INTO journal_usage SELECT 'events',COALESCE(SUM(LENGTH(CAST(payload AS BLOB))),0) FROM events WHERE NOT EXISTS(SELECT 1 FROM journal_usage WHERE name='events');
                CREATE TRIGGER IF NOT EXISTS event_bytes_insert AFTER INSERT ON events BEGIN
                  UPDATE journal_usage SET value=value+LENGTH(CAST(NEW.payload AS BLOB)) WHERE name='events';
                END;
                CREATE TRIGGER IF NOT EXISTS event_bytes_delete AFTER DELETE ON events BEGIN
                  UPDATE journal_usage SET value=value-LENGTH(CAST(OLD.payload AS BLOB)) WHERE name='events';
                END;
            """)
        if os.name != "nt":
            self.path.chmod(0o600)

    @contextmanager
    def db(self) -> Iterator[sqlite3.Connection]:
        db = sqlite3.connect(self.path, timeout=5)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA synchronous=FULL")
        if self.path.stat().st_size == 0:
            db.execute("PRAGMA auto_vacuum=INCREMENTAL")
        try:
            cap = db.execute("SELECT value FROM journal_limits WHERE name='audit_bytes'").fetchone()[0]
        except (sqlite3.OperationalError, TypeError):
            cap = 1024 * 1024 * 1024
        page_size = db.execute("PRAGMA page_size").fetchone()[0]
        # SQLite rejects growth beyond this physical database bound, including
        # indexes/reviews/run metadata. Failure prevents subsequent dispatch.
        db.execute("PRAGMA max_page_count=" + str(max(1, int(cap) // page_size)))
        try:
            with db:
                yield db
        finally:
            db.close()

    def event(self, kind: str, *, run: str | None = None, event_id: str | None = None, **payload: Any) -> str:
        with self.db() as db:
            return self._append_event(db, kind, run=run, event_id=event_id, **payload)

    def _append_event(self, db: sqlite3.Connection, kind: str, *, run: str | None = None, event_id: str | None = None, **payload: Any) -> str:
        event_id = event_id or uuid4().hex
        now = time.time()
        item = journal_redact({**payload, "event_id": event_id, "type": kind, "run_id": run, "created_at": now})
        # 'value' here contains derived classes/length, never raw field contents.
        # Preserve those typed facts after generic secret-key redaction.
        for key in ("facts", "specific_facts"):
            facts = payload.get(key)
            if isinstance(facts, dict) and isinstance(facts.get("value"), dict):
                value = facts["value"]
                item[key]["value"] = {k: v for k, v in value.items() if
                    (k == "present" and isinstance(v, bool)) or
                    (k == "length" and isinstance(v, int)) or
                    (k == "classes" and isinstance(v, list) and all(isinstance(x, str) and len(x) < 64 for x in v))}

        payload_json = json.dumps(item, separators=(",", ":"))
        if len(payload_json.encode()) > 1024 * 1024:
            raise OSError("Required audit record exceeds the 1 MiB per-record bound")
        db.execute("INSERT OR IGNORE INTO events(id,run,created,payload) VALUES(?,?,?,?)",
                   (event_id, run, now, payload_json))
        cap = db.execute("SELECT value FROM journal_limits WHERE name='audit_bytes'").fetchone()[0]
        size = db.execute("SELECT value FROM journal_usage WHERE name='events'").fetchone()[0]
        payload_budget = cap * .65
        if size > payload_budget:
            removed = 0
            # Bounded work at an authorization boundary. Maintenance handles large
            # reductions; until then a run stops rather than growing without bound.
            for _ in range(10):
                removed += db.execute("DELETE FROM events WHERE seq IN (SELECT seq FROM events WHERE id!=? ORDER BY seq LIMIT 500)", (event_id,)).rowcount
                size = db.execute("SELECT value FROM journal_usage WHERE name='events'").fetchone()[0]
                if size <= payload_budget * .9:
                    break
            if size > payload_budget * .9:
                raise OSError("Audit storage limit reached; run acira sync to prune retained history")
            marker = {"event_id":uuid4().hex,"type":"history_pruned","created_at":now,"removed":removed,"byte_limit":cap}
            db.execute("INSERT INTO events(id,created,payload) VALUES(?,?,?)", (marker["event_id"],now,json.dumps(marker)))
        return event_id

    def latest_sequence(self) -> int:
        with self.db() as db:
            return db.execute("SELECT COALESCE(MAX(seq),0) FROM events").fetchone()[0]

    def events(self, *, run: str | None = None, after: int = 0, limit: int = 500,
               before: int | None = None, through: int | None = None, descending: bool = False,
               query: str = "", kind: str | None = None, agent: str | None = None) -> list[dict[str, Any]]:
        conditions = ["seq>?"]
        parameters: list[Any] = [after]
        for clause, value in (("run=?", run), ("seq<?", before), ("seq<=?", through),
                              ("json_extract(payload,'$.type')=?", kind),
                              ("json_extract(payload,'$.agent')=?", agent)):
            if value is not None:
                conditions.append(clause)
                parameters.append(value)
        if query:
            conditions.append("instr(lower(payload),lower(?))>0")
            parameters.append(query[:500])
        parameters.append(min(max(limit, 1), 5000))
        with self.db() as db:
            rows = db.execute("SELECT seq,payload FROM events WHERE " + " AND ".join(conditions)
                              + (" ORDER BY seq DESC" if descending else " ORDER BY seq") + " LIMIT ?", parameters).fetchall()
        return [{**json.loads(row["payload"]), "sequence": row["seq"]} for row in rows]

    def record_pending(self, record: Any) -> None:
        self.event("action_proposed", run=record.run_id, operation_id=record.review_id, **{k: v for k, v in asdict(record).items() if k not in {"run_id", "created_at"}})

    def record_decision(self, review_id: str, *, status: str, reason: str | None, metadata: dict[str, Any] | None) -> None:
        self.event("action_decision", operation_id=review_id, status=status, reason=reason, metadata=metadata)

    def update_run(self, run: str, payload: dict[str, Any]) -> None:
        now = time.time()
        with self.db() as db:
            db.execute("INSERT INTO runs VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET updated=excluded.updated,payload=excluded.payload",
                       (run, now, json.dumps(journal_redact({**payload, "run_id": run, "heartbeat_at": now}))))

    def runs(self) -> list[dict[str, Any]]:
        with self.db() as db:
            rows = db.execute("SELECT * FROM runs ORDER BY updated DESC").fetchall()
        now = time.time()
        result = []
        for row in rows:
            payload = json.loads(row["payload"])
            if payload.get("state") not in {"ended", "failed"} and now - row["updated"] > 15:
                payload["state"] = "disconnected"
            result.append(payload)
        return result

    def control(self, run: str, desired: str | None = None) -> str:
        with self.db() as db:
            if desired is not None:
                if desired not in {"running", "paused"}:
                    raise ValueError("Only acknowledged pause/resume is supported")
                if not db.execute("SELECT 1 FROM runs WHERE id=?", (run,)).fetchone():
                    raise ValueError("Unknown run")
                db.execute("INSERT INTO controls VALUES(?,?) ON CONFLICT(run) DO UPDATE SET desired=excluded.desired", (run, desired))
            row = db.execute("SELECT desired FROM controls WHERE run=?", (run,)).fetchone()
        return row[0] if row else "running"

    def create_review(self, run: str, payload: dict[str, Any], *, timeout: float = 300) -> dict[str, Any]:
        review_id = uuid4().hex
        expires = time.time() + min(max(timeout, 1), 300)
        item = journal_redact({**payload, "review_id": review_id, "run_id": run, "expires_at": expires, "state": "pending"})
        with self.db() as db:
            db.execute("INSERT INTO reviews VALUES(?,?,?,?,?)", (review_id, run, "pending", expires, json.dumps(item)))
            self._append_event(db, "review_requested", run=run, review=item)
        return item

    def review(self, review_id: str) -> dict[str, Any]:
        with self.db() as db:
            row = db.execute("SELECT * FROM reviews WHERE id=?", (review_id,)).fetchone()
        if row is None:
            raise ValueError("Unknown review")
        state = row["state"]
        if state == "pending" and time.time() >= row["expires"]:
            self.decide(review_id, "expired")
            return self.review(review_id)
        return {**json.loads(row["payload"]), "state": state}

    def reviews(self) -> list[dict[str, Any]]:
        with self.db() as db:
            ids = [row[0] for row in db.execute("SELECT id FROM reviews ORDER BY expires DESC LIMIT 1000")]
        return [self.review(review_id) for review_id in ids]

    def decide(self, review_id: str, decision: str, *, grant: bool = False) -> bool:
        if decision not in {"approved", "rejected", "expired", "invalidated"}:
            raise ValueError("Invalid review decision")
        with self.db() as db:
            db.execute("BEGIN IMMEDIATE")
            row = db.execute("SELECT * FROM reviews WHERE id=?", (review_id,)).fetchone()
            if row is None:
                raise ValueError("Unknown review")
            if row["state"] != "pending":
                return False
            item = json.loads(row["payload"])
            if time.time() >= row["expires"]:
                decision = "expired"
            if grant and not item.get("grant_eligible"):
                raise ValueError("This operation cannot receive a reusable grant")
            item["grant_requested"] = grant and decision == "approved"
            db.execute("UPDATE reviews SET state=?,payload=? WHERE id=?", (decision, json.dumps(item), review_id))
            self._append_event(db, "review_decided", run=row["run"], review_id=review_id, decision=decision)
        return True

    def retention(self, *, days: int = 30, cap: int = 1024 * 1024 * 1024, image_days: int = 7, image_cap: int = 250 * 1024 * 1024) -> None:
        with self.db() as db:
            db.execute("UPDATE journal_limits SET value=? WHERE name='audit_bytes'", (cap,))
            db.execute("UPDATE journal_limits SET value=? WHERE name='image_bytes'", (image_cap,))
            expired = db.execute("SELECT id,run FROM grants WHERE expires<?", (time.time(),)).fetchall()
            for row in expired:
                self._append_event(db, "grant_expired", run=row["run"], grant_id=row["id"])
            removed = db.execute("DELETE FROM events WHERE created<?", (time.time() - days * 86400,)).rowcount
            db.execute("DELETE FROM reviews WHERE expires<? AND state!='pending'", (time.time() - 7 * 86400,))
            db.execute("DELETE FROM grants WHERE expires<?", (time.time(),))
            size = db.execute("SELECT value FROM journal_usage WHERE name='events'").fetchone()[0]
            if size > cap * .65:
                rows = db.execute("SELECT seq,LENGTH(CAST(payload AS BLOB)) FROM events ORDER BY seq").fetchall()
                cutoff = 0
                for row in rows:
                    size -= row[1]
                    cutoff = row[0]
                    if size <= cap * .6:
                        break
                removed += db.execute("DELETE FROM events WHERE seq<=?", (cutoff,)).rowcount
            if removed:
                self._append_event(db, "history_pruned", removed=removed, retention_days=days, byte_limit=cap)
            db.execute("DELETE FROM controls WHERE run IN (SELECT id FROM runs WHERE updated<?)", (time.time()-days*86400,))
            db.execute("DELETE FROM runs WHERE updated<?", (time.time()-days*86400,))
        # Reclaim free pages after pruning. This is bounded by SQLite's busy
        # timeout; it does not run during an active journal transaction.
        with self.db() as db:
            db.execute("PRAGMA incremental_vacuum")
        if self.path.stat().st_size > cap:
            with self.db() as db:
                db.execute("VACUUM")
            if self.path.stat().st_size > cap:
                raise OSError("Runtime metadata exceeds the audit storage limit; increase it before continuing")
        from .local import file_lock
        with file_lock(self.path.parent / "images.lock"):
            artifacts = self.path.parent / "artifacts"
            paths = sorted(artifacts.glob("*.png"), key=lambda path: path.stat().st_mtime)
            total = sum(path.stat().st_size for path in paths)
            for path in paths:
                if path.stat().st_mtime < time.time() - image_days * 86400 or total > image_cap:
                    size = path.stat().st_size
                    path.unlink()
                    total -= size

    def store_artifact(self, artifact: dict[str, Any]) -> dict[str, Any]:
        metadata = {key: value for key, value in artifact.items() if key != "image"}
        if not artifact.get("image"):
            return metadata
        data = base64.b64decode(artifact["image"], validate=True)
        if not data.startswith(b"\x89PNG\r\n\x1a\n") or len(data) > 10 * 1024 * 1024:
            raise ValueError("Invalid or oversized review image")
        identifier = secrets.token_hex(16) + ".png"
        path = self.path.parent / "artifacts" / identifier
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        with self.db() as db:
            cap = db.execute("SELECT value FROM journal_limits WHERE name='image_bytes'").fetchone()[0]
        if len(data) > cap:
            return {"capture_status":"unavailable","reason":"Masked screenshot exceeds the configured image storage limit"}
        # Concurrent runs share the same image budget.
        from .local import file_lock
        with file_lock(self.path.parent / "images.lock"):
            images = sorted(path.parent.glob("*.png"), key=lambda item:item.stat().st_mtime)
            total = sum(item.stat().st_size for item in images)
            for previous in images:
                if total + len(data) <= cap:
                    break
                total -= previous.stat().st_size
                previous.unlink()
            self._write_artifact(path, data)
        return {**metadata, "id": identifier}

    @staticmethod
    def _write_artifact(path: Path, data: bytes) -> None:
        with path.open("xb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        if os.name != "nt":
            path.chmod(0o600)
